/**
 * Wire protocol - JSON text frames in both directions.
 *
 * Client -> server:
 *
 * 	{"type":"subscribe","id":"<client-chosen>","topic":"<kind>","params":{...}}
 * 	{"type":"unsubscribe","id":"<same id>"}
 *
 * id is opaque to the server and just tags every message about that
 * subscription; subscribing again with an id already in use replaces the
 * old subscription.
 *
 * Server -> client:
 *
 * 	{"type":"snapshot","id":"...","data":<full value>}
 * 	{"type":"patch","id":"...","ops":[<Op>...]}
 * 	{"type":"error","id":"...","status":404,"error":"book not found"}
 *
 * A subscription always starts with a snapshot or an error. A patch
 * applies to the value the client currently holds for that id. After an
 * error the next message for the id (if the topic recovers) is a fresh
 * snapshot, never a patch.
 */
@Serializable
data class ClientMessageDto(
    val type: String = "",
    val id: String = "",
    val topic: String = "",
    val params: JsonElement? = null,
)

/**
 * CloneModelInfo describes one clone model (store.Book.CloneModel).
 */
@Serializable
data class CloneModelInfoDto(
    val id: String = "",
    val label: String = "",
    /**
     * DefaultTemperature is the model's own sampling temperature, for a
     * model whose session reads a "temperature" option at all (nil: no
     * such knob - flow/diffusion models, OmniVoice).
     */
    val defaultTemperature: Double? = null,
)

/**
 * contentItemDTO gives the frontend chapter content in original document
 * order (text interleaved with images). Text items point back into
 * `paragraphs` by index rather than duplicating its fields, since
 * `paragraphs` is also what playback/position logic indexes into directly.
 *
 * apigen:ts-hand - the frontend models this as a discriminated union on
 * Kind instead.
 */
@Serializable
data class ContentItemDto(
    /**
     * "text" | "image" | "break"
     */
    val kind: String = "",
    /**
     * No omitempty: 0 is a valid, common paragraphIdx (the first paragraph
     * of a chapter), and omitempty would silently drop it.
     */
    val paragraphIdx: Int = 0,
    val imageUrl: String? = null,
    /**
     * Inline mirrors the referenced paragraph's own Inline (see
     * paragraphDTO.Inline) - duplicated here so the frontend's
     * content-ordering pass can decide paragraph breaks without a second
     * lookup into `paragraphs`.
     */
    val inline: Boolean = false,
)

