/**
 * musicRegionDTO is one store.MusicRegion, reshaped for the frontend's own
 * background-music playback engine (see store.MusicRegion's own doc
 * comment for the generation pipeline this reflects). AudioURL is only
 * set once Status is AudioReady - the same "no URL until it means
 * something" convention paragraphDTO already uses.
 */
@Serializable
data class MusicRegionDto(
    val id: String = "",
    val startIdx: Int = 0,
    val endIdx: Int = 0,
    val mood: String = "",
    /**
     * Prompt is the actual Stable Audio generation prompt ScoreMusic wrote
     * for this region (store.MusicRegion.Prompt) - Mood is just a short
     * label for compact display (table/badge text); Prompt is the fuller
     * "score" a reader can see without needing to actually hear the
     * result, surfaced by the reader's annotations view as this region's
     * own boundary marker tooltip (see ChapterSection.MusicRegionBoundary).
     */
    val prompt: String = "",
    /**
     * Ambience is the region's ambient-soundscape prompt
     * (store.MusicRegion.Ambience), mixed under the music - "" for none.
     */
    val ambience: String? = null,
    /**
     * "cut" or "continuation" - see store.MusicTransition
     */
    val transition: String = "",
    /**
     * Lighting is the region's room-lighting cue from the ambience pass's
     * lighting sub-pass - absent until that sub-pass reaches the region.
     * Clients drive the actual lights (Philips Hue) from it themselves.
     */
    val lighting: LightingDto? = null,
    val status: AudioStatus = "",
    val error: String? = null,
    val durationSeconds: Double = 0.0,
    val audioUrl: String? = null,
)

@Serializable
data class ParagraphDto(
    val idx: Int = 0,
    val text: String = "",
    val audioStatus: AudioStatus = "",
    val audioError: String? = null,
    val durationSeconds: Double? = null,
    val audioUrl: String? = null,
    /**
     * AudioPointerSeconds is set only when this paragraph is a scare-quote
     * merge group pointer (store.AudioState.PointerOffset > 0): the time,
     * in seconds within AudioURL's own shared clip, where this paragraph's
     * own content actually begins - AudioURL itself already resolves to
     * whichever paragraph holds that shared recording (see resolveAudioID).
     * The frontend player uses this to know when playback (which it never
     * seeks or restarts at a merge group's own internal boundaries - see
     * usePlayback.ts) has reached this paragraph's own span, for
     * highlighting/position-reporting purposes only. Omitted (0) for a
     * paragraph with its own real file, which always begins at the very
     * start of AudioURL's clip.
     */
    val audioPointerSeconds: Double = 0.0,
    /**
     * Speaker is "" (never attributed) or "Narrator", or a character name -
     * see store.Paragraph.Speaker. Only actually changes this paragraph's
     * narration voice when the book has MultiVoice on (see
     * internal/narration.Resolver) and the named character has a voice
     * assigned - otherwise purely informational.
     */
    val speaker: String? = null,
    /**
     * SpeakerIndex tells apart several unnamed people sharing Speaker's
     * role label in one conversation ("Guard 2") - see
     * store.Paragraph.SpeakerIndex. Omitted (0) for a line with no number.
     */
    val speakerIndex: Int? = null,
    /**
     * Label is text to show before this paragraph that is never spoken: a
     * play's speaker label ("THESEUS.") and any direction on how the line
     * is delivered - see store.Paragraph.Label. Omitted outside a play.
     */
    val label: String? = null,
    /**
     * Inline marks this paragraph as a split-out continuation of the
     * previous one, not the start of a new visual paragraph - see
     * store.Paragraph.Inline. The frontend should render consecutive
     * Inline paragraphs (and contentItemDTO's own Inline, below) joined
     * into one paragraph block rather than with a break between them,
     * while still treating each as its own playback/highlight unit.
     */
    val inline: Boolean = false,
    /**
     * IsQuote marks this as an actual quoted-dialogue span, as opposed to
     * narration/description - see store.Paragraph.IsQuote. This, not
     * Speaker being non-empty, is what tells the frontend's annotations
     * view a segment is dialogue: an unattributed quote still has
     * Speaker == "" but is dialogue all the same.
     */
    val isQuote: Boolean = false,
    /**
     * ScareQuote marks an IsQuote paragraph as NOT actually spoken dialogue
     * despite looking like it structurally - see store.Paragraph.ScareQuote.
     * Always false for a non-IsQuote paragraph.
     */
    val scareQuote: Boolean = false,
    /**
     * Emotion is this paragraph's effective delivery emotion (an
     * internal/emotions id - see store.Paragraph.EffectiveEmotion), omitted
     * for neutral. Only ever set on real dialogue.
     */
    val emotion: String? = null,
    /**
     * DirectionMarks is every inline delivery tag (today only Higgs's
     * "<|prosody:pause|>") the generation text for this paragraph carries
     * under whichever clone model it's resolved to narrate through, each
     * pinned to where it's inserted in Text (see directionMarkDTO.Offset)
     * so the frontend can render an inline caret there. Empty for the
     * common case.
     */
    val directionMarks: List<DirectionMarkDto> = emptyList(),
    /**
     * PronunciationMarks is every resolved pronunciation substitution
     * active on this paragraph (e.g. "Dr." -> "Doctor"), each pinned to
     * the word it replaces (see pronunciationMarkDTO.Offset) so the
     * frontend can render a caret directly over it. Unlike DirectionMarks,
     * not clone-model-scoped - see store.Paragraph.Pronunciation's own
     * doc comment. Empty for the common case (no ambiguous abbreviation
     * found in this paragraph).
     */
    val pronunciationMarks: List<PronunciationMarkDto> = emptyList(),
    /**
     * Table is set for a paragraph read from a table in the source book.
     */
    val table: TableDto? = null,
    /**
     * Words is a [{text,start,end}] array from the ttsworker's
     * forced alignment (see ttsworker.Manager.Align), or "[]" before
     * alignment has run - always present (unlike the websocket push's
     * Words, which is omitted for updates that aren't about alignment)
     * since this is a full paragraph snapshot, not a patch.
     */
    val words: List<WordTimingDto> = emptyList(),
    /**
     * SFX* mirror store.Paragraph's own sound-effect test fields - see
     * its doc comments. SFXAudioURL is set only once SFXStatus ==
     * store.AudioReady, the same "URL only when actually fetchable"
     * convention AudioURL follows.
     */
    val sfxPrompt: String? = null,
    val sfxStatus: String? = null,
    val sfxError: String? = null,
    val sfxAudioUrl: String? = null,
    val sfxDurationSeconds: Double? = null,
    /**
     * SFXTriggerWord mirrors store.Paragraph.SFXTriggerWord - which word
     * (a 0-based index into Words above) playback should start the sound
     * effect at, once ready.
     */
    val sfxTriggerWord: Int? = null,
    /**
     * ContentHash/AudioHash are this paragraph's leaves in the offline-sync
     * hash tree (see manifest.go): ContentHash covers what an offline copy
     * stores about the paragraph's text and annotations, AudioHash what
     * identifies its audio (resolved voice, status, backing clip, duration,
     * pointer) - so a client can tell "refresh the metadata" apart from
     * "re-download the .wav".
     */
    val contentHash: String = "",
    val audioHash: String = "",
)

/**
 * paragraphEditDTO is one recorded manual correction (store.ParagraphEdit):
 * the machine's value before the first edit, and the reader's latest.
 * Speakers read "Narrator" where the store holds "".
 */
@Serializable
data class ParagraphEditDto(
    val chapterIdx: Int = 0,
    val paragraphIdx: Int = 0,
    val field: ParagraphEditField = "",
    val original: String = "",
    val value: String = "",
    val editedAt: Long = 0L,
    val text: String = "",
)

@Serializable
data class ParagraphEditsResponseDto(
    val edits: List<ParagraphEditDto> = emptyList(),
)

/**
 * Passes is a chapter's own book-preprocess pipeline progress
 * (chapters.passes, stored as a JSON object - the same "flexible,
 * independent facts" shape tts_tags/pronunciation
 * already use their own JSON columns for, rather than one forward-only
 * ChapterState enum this replaced). A struct, not a map, on the Go side so
 * call sites get a typed field (ch.Passes.Direction) instead of a
 * string-keyed lookup a typo could silently miss; the column itself
 * stays a flexible JSON object so a future pass can be added as just
 * another field with no schema change.
 */
@Serializable
data class PassesDto(
    /**
     * Attribution is set once speaker attribution
     * (internal/speakerattr.Client.AttributeChapter, via
     * httpapi.attributeChapter) has completed over the whole chapter at
     * least once, in one uninterrupted pass (possibly across several
     * paused/resumed continuations - never set on a pause or a genuine
     * failure partway through, only a full completion).
     */
    val attribution: Boolean = false,
    /**
     * ScareQuote is set once scare-quote tagging
     * (internal/speakerattr.Client.ScareQuoteChapter, a jobs.KindScareQuote
     * task - see httpapi.scareQuoteChapterForJob) has completed over the
     * whole chapter, persisting Store.SetParagraphScareQuotes. Both
     * attribution waits on this
     * (jobs.Manager.scareQuoteDependency).
     */
    val scareQuote: Boolean = false,
    /**
     * Direction is set once emotion labeling
     * (internal/speakerattr.Client.EmotionChapter, via
     * httpapi.directChapter - any clone model) has completed over the whole
     * chapter at least once, the same "full pass, not a pause/failure" contract as
     * Attribution. Fully independent of Attribution - a
     * reader can trigger "Tag directions" directly on a chapter that was
     * never attributed via the per-chapter button, bypassing
     * runBookPipeline's own attribute-then-tag ordering entirely, and this
     * struct (unlike the old single ChapterState enum it replaced)
     * represents that combination just fine.
     */
    val direction: Boolean = false,
    /**
     * Pronunciation is set once pronunciation resolution
     * (internal/speakerattr.Client.ResolvePronunciation, a
     * jobs.KindPronunciation task via httpapi.pronounceChapter) has
     * completed a full pass over the chapter - Direction's own contract,
     * but its own pass.
     */
    val pronunciation: Boolean = false,
    /**
     * Ambience is set once the ambience pass's music sub-pass
     * (internal/speakerattr.Client.ScoreMusic, via httpapi.ambienceChapter)
     * has completed a full, uninterrupted pass over this chapter (never on
     * a pause or a genuine failure partway through) - Direction's own
     * "full pass, not a pause/failure" contract, and just as independent of
     * Attribution/Direction as Direction itself is: a reader
     * can trigger the ambience pass for a chapter regardless of whether
     * it's ever been attributed/direction-tagged. Triggered by
     * httpapi.handleRunChapterAmbience (the Speakers page's per-chapter
     * button/bulk actions, book preprocessing's own ambience phase, or the
     * reader lazily running whichever chapter it's currently on) -
     * deliberately NOT gated on store.Book.MusicEnabled: that toggle only
     * controls whether a scored region's audio actually gets generated
     * (jobs.Manager.MaybeAdvanceChapterMusic), not whether scoring itself
     * can run (see Book.MusicEnabled's own doc comment). Stored as
     * "music" until the pass was renamed (and backfilled by hand).
     */
    val ambience: Boolean = false,
    /**
     * Lighting is set once the ambience pass's lighting sub-pass
     * (internal/speakerattr.Client.DescribeLighting, via
     * httpapi.lightChapter) has given every one of the chapter's music
     * regions a MusicRegion.Lighting cue. Runs after the music sub-pass in
     * the same task (it lights the regions scoring produced), but is its
     * own flag so a chapter scored before lighting existed - Ambience set,
     * Lighting not - gets just the lighting sub-pass on its next ambience
     * run, without re-scoring its music.
     */
    val lighting: Boolean = false,
    /**
     * Summary is set once the summary pass (internal/speakerattr.Client.
     * SummarizeChapter, a jobs.KindSummary task via httpapi.
     * summarizeChapter) has stored the chapter's ChapterNotes. Speaker
     * attribution and the ambience pass wait on it (jobs.Manager.
     * summaryDependency) to read its cast and scenes.
     */
    val summary: Boolean = false,
)

