@Serializable
data class SpeakerStageDto(
    val id: String = "",
    val bookId: String = "",
    val bookTitle: String = "",
    val chapterId: String = "",
    val chapterIdx: Int = 0,
    val chapterTitle: String = "",
    val age: Int = 0,
